CREATE TRIGGER trg_agenda_sync_agendamentos AFTER INSERT OR DELETE OR UPDATE ON public.agendamentos FOR EACH STATEMENT EXECUTE FUNCTION bump_agenda_sync_state();
CREATE TRIGGER trg_agendamentos_updated_at BEFORE UPDATE ON public.agendamentos FOR EACH ROW EXECUTE FUNCTION set_updated_at();
