CREATE TRIGGER trg_clube_notificar_boleto_status AFTER UPDATE OF status ON public.boletos FOR EACH ROW WHEN ((old.status IS DISTINCT FROM new.status)) EXECUTE FUNCTION clube_notificar_boleto_status();
